type Error struct {
	// A unique, machine-readable and stable code that identifies this error. Must be consistent across all
	// services and provide clear categorization. Format: `category.subcategory.specificError`.
	Code string `json:"code"`
	// A short, human-readable summary of the problem that doesn't change from occurrence to occurrence of
	// the problem. Should provide immediate understanding of the error type.
	Title string `json:"title"`
	// A human-readable explanation specific to this occurrence of the problem. May include suggestions for
	// resolution but should not expose sensitive information.
	Detail string         `json:"detail"`
	Source OptErrorSource `json:"source"`
}

// GetCode returns the value of Code.
func (s *Error) GetCode() string {
	return s.Code
}

// GetTitle returns the value of Title.
func (s *Error) GetTitle() string {
	return s.Title
}

// GetDetail returns the value of Detail.
