// Configuration for field values. Provides inline data for small sets and/or a reference link for
// large/dynamic sets.
//
// Interpretation:
//
//   - `data` only → Complete set inline
//   - `data` + `links.next` → Preview in data, full list at link
//   - `data` empty + `links.next` → Fully dynamic, fetch from link
//
// Ref: #/components/schemas/FieldValues
type FieldValues struct {
	// Inline value options. Can be empty. For small sets: contains all values. For large sets: contains
	// preview or empty.
	Data  []FieldValueItem    `json:"data"`
	Links OptFieldValuesLinks `json:"links"`
}

